  ui_story_40110001_159_dialog_content = "...",
  ui_story_40110001_160_dialog_content = "¡¿Por qué de repente hay guardias armados corriendo hacia mí?!",
  ui_story_40110001_161_dialog_content = "¡Detente!",
  ui_story_40110001_162_dialog_content = "*Ejem* ¿C-cuál es el problema? Te haré saber, fui invitado aquí por gente importante en Lumopolis...",
