  ui_story_40110001_165_dialog_content = "Tú... ¿Por qué tienes tanto miedo?",
  ui_story_40110001_166_dialog_content = "¿Q-quién tiene miedo? ¡Estoy perfectamente tranquilo!",
  ui_story_40110001_167_dialog_content = "Estás temblando tanto que estás dejando caer todas tus flores...",
  ui_story_40110001_168_dialog_content = "¡Ah, es porque llevo demasiadas!",
