  ui_story_40110001_170_dialog_content = "¿Eh? E-Está bien... Gracias...",
  ui_story_40110001_171_dialog_content = "<color=#e8d9bb>El guardia recogió un gran ramo de flores antes de correr hacia un gran grupo de personas.</color>",
  ui_story_40110001_172_dialog_content = "<color=#e8d9bb>Uriah estaba en el centro de la multitud, aparentemente hablando con la gente que la rodeaba...</color>",
  ui_story_40110001_173_dialog_content = "Gracias a todos por venir hoy a nuestro recital de poesía.",
  ui_story_40110001_174_dialog_content = "Hoy, nos gustaría expresar nuestro más sincero dolor y duelo.",
  ui_story_40110001_175_dialog_content = "Hoy, nos gustaría conmemorar a nuestro querido amigo.",
  ui_story_40110001_176_dialog_content = "Por nuestro amigo.",
  ui_story_40110001_177_dialog_content = "Una vez, una gran y devastadora guerra afectó a esta tierra, y muchos se perdieron por la amenaza Eclipsite ...",
  ui_story_40110001_178_dialog_content = "Algunos los vieron como el enemigo, otros como una fuerza ciega y destructiva de la naturaleza ...",
  ui_story_40110001_179_dialog_content = "<color=#e8d9bb>Después de decir esto, Uriah comenzó a repartir flores blancas a cada persona en la multitud.</color>",
  ui_story_40110001_180_dialog_content = "<color=#e8d9bb>Y Chloe comenzó a cantar la canción \"Flor Blanca\".</color>",
  ui_story_40110001_181_dialog_content = "<color=#e8d9bb>Los niños de Keating, en lugar de provocar problemas como de costumbre, estaban consolando en silencio a un invitado que lloraba.</color>",
  ui_story_40110001_182_dialog_content = "<color=#e8d9bb>Fue un pequeño funeral, y todo lo que estaban haciendo antes era para prepararlo.</color>",
  ui_story_40110001_183_dialog_content = "Así que el concurso de poesía... fue elegir qué poema se recitaría aquí...",
