  ui_story_40110001_185_option_content = "Preguntar a Uriah.",
  ui_story_40110001_186_dialog_content = "Navegador, ¿te acuerdas de la flor blanca que te di antes?",
  ui_story_40110001_187_dialog_content = "Sí.",
  ui_story_40110001_188_dialog_content = "Ese día me preguntaste por mi historia, pero la verdad es que no tengo ninguna historia...",
  ui_story_40110001_189_dialog_content = "No soy más que una persona común, una que sobrevivió abandonando la línea de frente hace mucho tiempo.",
  ui_story_40110001_190_dialog_content = "Mi familia, mis amigos... Todos ellos vivos y bien.",
  ui_story_40110001_191_dialog_content = "Una persona me preguntó una vez: \"¿Qué podrías saber sobre el dolor de perder a alguien?\"",
  ui_story_40110001_192_dialog_content = "¿Fue durante un funeral que estaba presidiendo?",
  ui_story_40110001_193_dialog_content = "Sí... Quizá mi enfoque no tuvo en cuenta tus sentimientos, y por eso pido disculpas.",
  ui_story_40110001_194_dialog_content = "Pero cuando los niños de Keating dijeron que querían invitarte al recital de poesía, estuve totalmente de acuerdo.",
  ui_story_40110001_195_dialog_content = "Navegador... A pesar de sus constantes lágrimas, Chloe realmente desea que sonrías más.",
  ui_story_40110001_196_dialog_content = "La señorita Vice está de acuerdo, por lo que también decidió prestarnos su ayuda.",
  ui_story_40110001_197_dialog_content = "Ah... Creo que ahora lo entiendo. Entonces, básicamente, esperas que pueda aceptar este \"recital de poesía\", ¿verdad?",
  ui_story_40110001_198_dialog_content = "Sí. Te creo... como todos los demás, tienes a aquellos a quienes deseas conmemorar.",
  ui_story_40110001_199_dialog_content = "Pero, ¿qué debo hacer? Si tengo gente que quiero recordar...",
  ui_story_40110001_200_dialog_content = "Puedes hacer lo que hacen los demás y poner flores en un campo para que se las lleve el viento.",
  ui_story_40110001_201_dialog_content = "Sí.",
  ui_story_40110001_202_option_content = "Preguntar a Chloe.",
  ui_story_40110001_203_dialog_content = "¿Estás bien? Tus ojos estaban llenos de lágrimas hace un momento... ¿El viento aquí te pica los ojos?",
  ui_story_40110001_204_dialog_content = "Ahora estoy bien, gracias por vigilarme.",
  ui_story_40110001_205_dialog_content = "Este recital de poesía... No se parece en nada a lo que esperaba.",
  ui_story_40110001_206_dialog_content = "Sí... No hay gran escenario, ni luces intermitentes...",
  ui_story_40110001_207_dialog_content = "Solo tierra, hierba y viento a nuestro alrededor... Pero aun así, estuvieron dispuestos a asistir.",
  ui_story_40110001_208_dialog_content = "\"Y lo sé, sí, lo sé, ¡tenemos que seguir adelante! ¡Pero nuestros recuerdos no se olvidan tan fácil!\"",
  ui_story_40110001_209_dialog_content = "\"Quizá nuestra felicidad estaba condenada desde el principio...”",
  ui_story_40110001_210_dialog_content = "\"Pero al mundo no le importa, ya que sigue girando...\"",
  ui_story_40110001_211_dialog_content = "\"Sueño con un paseo junto a un lago lejano...\"",
  ui_story_40110001_212_dialog_content = "\"De pájaros can. canciones en la estela del sol poniente...\"",
  ui_story_40110001_213_dialog_content = "\"Y lo sé, sí, lo sé, ¡tenemos que seguir adelante! ¡Pero nuestros recuerdos no se olvidan tan fácil!\"",
  ui_story_40110001_214_dialog_content = "\"¿Se desvanecerán nuestros recuerdos de ese campo o nuestros corazones?\"",
  ui_story_40110001_215_dialog_content = "\"Pero todavía hay mucho dolor que aún no se ha ido...\"",
  ui_story_40110001_216_dialog_content = "\"Todo lo que puedo hacer es poner flores en esta llanura... Y espero que el viento se los lleve con mi dolor.\"",
  ui_story_40110001_217_option_content = "Pregúntale a Keating.",
  ui_story_40110001_218_dialog_content = "Parece que Chloe terminó con su canción.",
  ui_story_40110001_219_dialog_content = "¿Qué pensaste?",
  ui_story_40110001_220_dialog_content = "¿Mmm? ¿Por qué me preguntas eso, de repente?",
  ui_story_40110001_221_dialog_content = "Parecía que lo disfrutabas en el Colossus.",
  ui_story_40110001_222_dialog_content = "Su canción es probablemente tu favorita, ¿no?",
  ui_story_40110001_223_dialog_content = "¿Eh? Oh, todavía estás hablando del concurso de poesía.",
  ui_story_40110001_224_dialog_content = "Pensé que me estabas molestando de nuevo.",
  ui_story_40110001_225_dialog_content = "¿Aún no estás seguro? ¿O solo no estás dispuesto a pensar en ello?",
  ui_story_40110001_226_dialog_content = "¡Para ya! Todo esto fue idea tuya, ¿no? Dime qué está pasando.",
  ui_story_40110001_227_dialog_content = "¡No antes de que nos digas tu favorito!",
  ui_story_40110001_228_dialog_content = "No intentes evadir la pregunta.",
  ui_story_40110001_229_dialog_content = "Estimado PlayerName.",
  ui_story_40110001_230_dialog_content = "Buscar la verdad es normal y bueno,",
  ui_story_40110001_231_dialog_content = "Pero primero debes pasar una prueba de la mente.",
  ui_story_40110001_232_dialog_content = "Y solo entonces la respuesta será tuya.",
  ui_story_40110001_233_dialog_content = "\"Algunos pierden a sus amantes,”",
  ui_story_40110001_234_dialog_content = "\"Algunos pierden a sus amigos.\"",
  ui_story_40110001_235_dialog_content = "\"Todo lo que quieren es volver a verlos,\"",
  ui_story_40110001_236_dialog_content = "Ahora, ¿cuál crees que debería ser la siguiente línea?",
  ui_story_40110001_237_dialog_content = "\"Pero todo lo que puedo ver son malas hierbas afuera de tu puerta.\"",
  ui_story_40110001_238_dialog_content = "Lo siento, creo que finalmente lo entiendo...",
  ui_story_40110001_239_dialog_content = "Ustedes no se estaban burlando de nadie ni estaban bromeando... Prepararon estos poemas con todo su corazón.",
  ui_story_40110001_240_dialog_content = "Sí.",
  ui_story_40110001_241_dialog_content = "Estimado PlayerName.",
  ui_story_40110001_242_dialog_content = "¡Aquí está, la verdad tan esperada!",
  ui_story_40110001_243_dialog_content = "¿De verdad creías que todo esto era para ti?",
  ui_story_40110001_244_dialog_content = "En realidad, fue una llamada de último minuto para que participaras.",
  ui_story_40110001_245_dialog_content = "Y solo necesitábamos que nos llevaran al lugar.",
  ui_story_40110001_246_dialog_content = "Ustedes... Supongo que Keating sigue igual que siempre...",
  ui_story_40110001_247_dialog_content = "<color=#e8d9bb> El viento se levantó de repente, llevándolos lejos mientras la multitud se juntaba.</color>",
  ui_story_40110001_248_dialog_content = "Debe ser Vice que viene a recogernos. ¿Volvemos juntos?",
